import java.util.*;

class Solution {
  public int longestAwesome(String s) {
    int[] first = new int[1 << 10];
    Arrays.fill(first, Integer.MAX_VALUE);
    first[0] = -1;
    int mask = 0, ans = 0;
    for (int i = 0; i < s.length(); i++) {
      mask ^= 1 << (s.charAt(i) - '0');
      if (first[mask] != Integer.MAX_VALUE) ans = Math.max(ans, i - first[mask]);
      else first[mask] = i;
      for (int b = 0; b < 10; b++) {
        int m = mask ^ (1 << b);
        if (first[m] != Integer.MAX_VALUE) ans = Math.max(ans, i - first[m]);
      }
    }
    return ans;
  }
}
